-- 空间目录只由根控制面使用；项目事实保存在独立 schema / PGlite 数据目录。
CREATE TABLE org_workspaces(id text PRIMARY KEY,name text NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE org_workspace_members(workspace_id text REFERENCES org_workspaces(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('admin','member')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE org_projects(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES org_workspaces(id),name text NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE org_project_members(project_id text REFERENCES org_projects(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('admin','operator','member')),PRIMARY KEY(project_id,user_id));
DROP INDEX IF EXISTS single_owner;
ALTER TABLE conversations ADD COLUMN archived_at timestamptz;
ALTER TABLE conversations ADD COLUMN agent_policy jsonb NOT NULL DEFAULT '{"observe":true,"muted":false,"mode":"observe"}';
CREATE TABLE conversation_forks(conversation_id text PRIMARY KEY REFERENCES conversations(id),parent_id text NOT NULL REFERENCES conversations(id),cutoff_seq integer NOT NULL,reason text NOT NULL,created_by text NOT NULL REFERENCES users(id));
CREATE TABLE group_read_watermarks(conversation_id text REFERENCES conversations(id),user_id text REFERENCES users(id),seq integer NOT NULL,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE goal_relations(id text PRIMARY KEY,source_id text NOT NULL REFERENCES collaboration_goals(id),target_id text NOT NULL REFERENCES collaboration_goals(id),kind text NOT NULL CHECK(kind IN ('depends_on','overlap','same','port','supersedes')),evidence text NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(source_id<>target_id),UNIQUE(source_id,target_id,kind));
CREATE TABLE work_handoffs(id text PRIMARY KEY,goal_id text NOT NULL REFERENCES collaboration_goals(id),from_user text NOT NULL REFERENCES users(id),to_user text NOT NULL REFERENCES users(id),goal_version integer NOT NULL,note text NOT NULL,state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE UNIQUE INDEX one_pending_handoff ON work_handoffs(goal_id) WHERE state='pending';
CREATE TABLE goal_revisions(id text PRIMARY KEY,goal_id text NOT NULL REFERENCES collaboration_goals(id),previous_version integer NOT NULL,snapshot jsonb NOT NULL,proposal jsonb NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'pending',created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_revision ON goal_revisions(goal_id) WHERE state='pending';
CREATE TABLE merge_proposals(id text PRIMARY KEY,source_id text NOT NULL REFERENCES collaboration_goals(id),target_id text NOT NULL REFERENCES collaboration_goals(id),source_version integer NOT NULL,target_version integer NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'proposed',created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE domain_outbox(id bigserial PRIMARY KEY,conversation_id text REFERENCES conversations(id),kind text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coordinator_leadership(id boolean PRIMARY KEY DEFAULT true CHECK(id),node_id text,epoch integer NOT NULL DEFAULT 1,lease_until timestamptz);
INSERT INTO coordinator_leadership(id) VALUES(true);
CREATE TABLE execution_limits(id boolean PRIMARY KEY DEFAULT true CHECK(id),max_devices integer NOT NULL DEFAULT 1 CHECK(max_devices BETWEEN 1 AND 10),max_parallel integer NOT NULL DEFAULT 1 CHECK(max_parallel BETWEEN 1 AND 10));
INSERT INTO execution_limits(id) VALUES(true);
DROP INDEX IF EXISTS single_active_device;
DROP INDEX IF EXISTS single_unresolved_attempt;
CREATE UNIQUE INDEX one_unresolved_per_device ON execution_attempts(device_id) WHERE status IN ('dispatching','running','cancelling','uncertain');
CREATE TABLE execution_resource_claims(attempt_id text REFERENCES execution_attempts(id),resource_key text NOT NULL,mode text NOT NULL CHECK(mode IN ('read','write')),epoch integer NOT NULL,PRIMARY KEY(attempt_id,resource_key));
CREATE TABLE execution_plans(id text PRIMARY KEY,goal_id text NOT NULL REFERENCES collaboration_goals(id),goal_version integer NOT NULL,state text NOT NULL DEFAULT 'draft',created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE execution_steps(id text PRIMARY KEY,plan_id text NOT NULL REFERENCES execution_plans(id),name text NOT NULL,input jsonb NOT NULL,dependencies jsonb NOT NULL,state text NOT NULL DEFAULT 'waiting',task_id text REFERENCES tasks(id),error_code text,UNIQUE(plan_id,name));
CREATE TABLE evaluation_cases(id text PRIMARY KEY,conversation_id text NOT NULL REFERENCES conversations(id),kind text NOT NULL,synthetic boolean NOT NULL,expected text NOT NULL,actual text NOT NULL,note text NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifact_validity(artifact_id text PRIMARY KEY REFERENCES artifacts(id),state text NOT NULL CHECK(state IN ('valid','stale','unverified')),reason text NOT NULL,updated_by text NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX relation_target ON goal_relations(target_id);
CREATE INDEX outbox_group_order ON domain_outbox(conversation_id,id);
